def-group:

    {{{ oval_metadata("The umask for root user of the bash shell", rule_title=rule_title) }}}





{{%- if product == "ubuntu2004" %}}

  {{#- CIS Ubuntu 20.04 5.4.2.6 reads these three files, and fails an octal umask
      that leaves group write or any other access, or a symbolic one that grants it. #}}

    ^(/root/\.bash_profile|/root/\.bashrc|/etc/login\.defs)$
    (?i)^[ \t]*umask[ \t]+(([0-7][0-7][01][0-7]\b|[0-7][0-7][0-7][0-6]\b)|([0-7][01][0-7]\b|[0-7][0-7][0-6]\b)|(u=[rwx]{1,3},)?(((g=[rx]?[rx]?w[rx]?[rx]?\b)(,o=[rwx]{1,3})?)|((g=[wrx]{1,3},)?o=[wrx]{1,3}\b)))
    1

{{%- else %}}


{{#- The CIS RHEL 7 audit reads /root/.bash_profile and /root/.bashrc, the files bash reads on RHEL. #}}
{{%- if product == "rhel7" %}}
  ^/root/\.(?:bash_profile|bashrc)$
{{%- else %}}
  ^(/root/.bashrc|/root/.profile)$
{{%- endif %}}
    ^[^#]*\bumask\s+[0-7]?[0-7]([0-1][0-7]|[0-7][0-6])\s*$
    1

{{%- endif %}}
